import java.io.*;
import java.util.*;

class Solution {
    public boolean containsPattern(int[] arr, int m, int k) {
        return false;
    }
}

public class Main {
    static int[] parseIntArray(String s) {
        s = s.trim();
        if (s.equals("[]")) return new int[0];
        s = s.substring(1, s.length() - 1).trim();
        if (s.isEmpty()) return new int[0];
        String[] parts = s.split(",");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i].trim());
        return a;
    }

    static List<String> topLevelArgs(String s) {
        s = s.trim();
        s = s.substring(1, s.length() - 1);
        List<String> out = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) {
                out.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        out.add(s.substring(start).trim());
        return out;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        List<String> parts = topLevelArgs(line);
        int[] arr = parseIntArray(parts.get(0));
        int m = Integer.parseInt(parts.get(1));
        int k = Integer.parseInt(parts.get(2));
        boolean result = new Solution().containsPattern(arr, m, k);
        System.out.println(result ? "true" : "false");
    }
}

